-- Exercise 10
-- a
-- Consult the settlement code, delivery, net weight, applied price, gross value, deductions, and net value for the settlements of that day, using the aliases: settlement, delivery, net weight kg, price per kg, gross cop, deductions cop, and net cop.

SELECT
    T1.settlement_id AS settlement,
    T1.delivery_id AS delivery,
    T1.net_weight_kg AS net_weight_kg,
    T1.price_per_kg_applied AS price_per_kg,
    T1.gross_amount AS gross_cop,
    T1.deductions_amount AS deductions_cop,
    T1.net_amount AS net_cop
FROM pay.settlements AS T1
WHERE T1.settlement_id LIKE 'STL-20260930-%'
ORDER BY T1.settlement_id ASC;
